var n=`0592-firni`;var t=`world-0592`;var o=`AF`;var r=`south-asia`;var a=8;var s=154;var l={en:`Firni`,ua:`Фірні`};var d={en:`A traditional dish from Afghanistan, centered on whole cow milk, cornstarch, pistachio. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Афганістан. Основні складники: цільне коров'яче молоко, кукурудзяний крохмаль, фісташка. Домашній варіант із кількостями продуктів за етапами приготування.`};var m=[{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 13 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 13 хвилин до м’якості та готовності.`,t:[`simmering`],m:13,i:[[`whole-cow-milk`,800,`ml`],[`white-granulated-sugar`,120,`g`],[`ground-cardamom`,5,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`cornstarch`,65,`g`],[`whole-cow-milk`,150,`ml`],[`rose-water`,15,`ml`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 130 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 130 хвилин.`,t:[`rapid-chilling`],m:130,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`pistachio`,50,`g`]]}];var g={slug:n,id:t,country:`AF`,region:r,servings:8,minutes:154,title:l,text:d,steps:m};export{o as country,g as default,t as id,s as minutes,r as region,a as servings,n as slug,m as steps,d as text,l as title};